T[12]={entrance={map=1413,x=42.3,y=89.9,zone={en="In the brambles at the southern tip of The Barrens",ko="불모의 땅 남쪽 끝 가시덤불 속"}},instanceIDs={47},key="rfk",levels="29-38",name={de="Kral von Razorfen",en="Razorfen Kraul",es="Horado Rajacieno",fr="Kraal de Tranchebauge",ko="가시덩굴 우리",ru="Лабиринты Иглошкурых",zhCN="剃刀沼泽",zhTW="剃刀沼澤"},nameMatch={"가시덩굴 우리","Razorfen Kraul","Kral von Razorfen","Kraal de Tranchebauge","Horado Rajacieno","Лабиринты Иглошкурых","剃刀沼泽","剃刀沼澤"},quests={{faction="Alliance",giver={en="Roogug's Vial of Phlogiston and other materials to Furen Longbeard in Stormwind (Warrior).",ko="루구그가 떨구는 연소 약병 등 재료를 스톰윈드 푸렌 롱비어드에게(전사)."},id=1701,level=28,minLevel=20,name={en="Fire Hardened Mail",ko="불에 달궈 만든 갑옷"}},{faction="Alliance",giver={en="Find and return Treshala's Pendant to Treshala Fallowbrook in Darnassus.",ko="트레샬라의 펜던트를 찾아 다르나서스에 있는 트레샬라 팰로우브룩에게 돌려주어야 합니다."},id=1142,level=30,minLevel=25,name={en="Mortality Wanes",ko="꺼져가는 생명의 불씨"}},{faction="Alliance",giver={en="Bring Razorflank's Medallion to Falfindel Waywarder in Thalanaar.",ko="탈라나르에 있는 팔핀델 웨이워더에게 차를가의 메달을 가져가야 합니다."},id=1101,level=34,minLevel=29,name={en="The Crone of the Kraul",ko="가시덩굴 우리의 대모"}},{faction="Horde",giver={en="15 Smoky Iron Ingots, 10 Powdered Azurite, 10 Iron Bars and Roogug's Vial of Phlogiston to Thun'grim Firegaze (Warrior).",ko="연기나는 철제 주괴 15개·아주라이트 가루 10개·철 주괴 10개·연소 약병(루구그)을 툰그림 파이어게이즈에게(전사)."},id=1838,level=30,minLevel=20,name={en="Brutal Armor",ko="투사의 방어구"}},{faction="Horde",giver={en="Bring 1 pile of Kraul Guano to Master Apothecary Faranell in the Undercity.",ko="언더시티에 있는 수석 연금술사 파라넬에게 가시덩굴 조분석을 가져가야 합니다."},id=1109,level=33,minLevel=30,name={en="Going, Going, Guano!",ko="조분석을 나에게!"}},{faction="Horde",giver={en="Bring Razorflank's Heart to Auld Stonespire in Thunder Bluff.",ko="썬더 블러프에 있는 아울드 스톤스파이어에게 차를가의 심장을 가져가야 합니다."},id=1102,level=34,minLevel=29,name={en="A Vengeful Fate",ko="운명의 복수"}},{giver={en="Grab a Crate with Holes. Grab a Snufflenose Command Stick. Grab and read the Snufflenose Owner's Manual. In Razorfen Kraul, use the Crate with Holes to summon a Snufflenose Gopher, and use the Command Stick on the gopher to make it search for Tubers. Bring 6 Blueleaf Tubers, the Snufflenose Command Stick and the Crate with Holes to Mebok Mizzyrix in Ratchet.",ko="구멍 난 상자를 집어야 합니다. 땅다람쥐 지휘봉도 챙겨야 합니다. 땅다람쥐 설명서를 찾아서 읽어야 합니다. 가시덩굴 우리에서 구멍 난 상자를 사용해 땅다람쥐를 소환하고 지휘봉을 사용해 땅다람쥐에게 청엽수 줄기를 찾아내도록 해야 합니다. 톱니항에 있는 메보크 미지릭스에게 청엽수 줄기 6개와 사용한 땅다람쥐 지휘봉과 구멍 난 상자를 가져가야 합니다."},id=1221,level=26,minLevel=20,name={en="Blueleaf Tubers",ko="청엽수 줄기"}},{giver={en="Escort Willix the Importer out of Razorfen Kraul.",ko="수입업자 윌릭스를 호위해 가시덩굴 우리에서 나가야 합니다."},id=1144,level=30,minLevel=22,name={en="Willix the Importer",ko="수입업자 윌릭스"}},{faction="Alliance",giver={en="Kill Charlga Razorflank and gather intel on the quilboar's plans (Shaman).",ko="서슬깃 차를가를 잡고 가시멧돼지의 계획 정보 모으기(주술사)."},id=96264,level=33,minLevel=30,name={en="Elemental Aid",ko="정기의 도움"}},{faction="Horde",giver={en="Kill Charlga Razorflank and gather intel on the quilboar's plans (Shaman).",ko="서슬깃 차를가를 잡고 가시멧돼지의 계획 정보 모으기(주술사)."},id=79360,level=33,minLevel=30,name={en="Elemental Aid",ko="정기의 도움"}},{faction="Horde",giver={en="Small Scroll from Charlga to Varimathras in the Undercity.",ko="차를가가 떨구는 작은 두루마리를 언더시티 바리마트라스에게."},id=6522,level=36,minLevel=28,name={en="An Unholy Alliance",ko="사악한 동맹"}}},slug="razorfen-kraul",steps={{id="s1",kind="boss",loot={274152,274155,274149,6841},model=6110,n="1",name={en="Roogug",ko="루구그"},npc={6168},quest=true,quests={1701,1838}},{id="s2",kind="boss",loot={6681,274159,274158},model=6097,n="2",name={en="Aggem Thorncurse",ko="저주의가시 아겜"},npc={4424}},{id="s3",kind="boss",loot={2816,6685,6682},model=4644,n="3",name={en="Death Speaker Jargba",ko="죽음의예언자 잘그바"},npc={4428}},{id="s4",kind="boss",loot={6687,6686,274161},model=4652,n="4",name={en="Overlord Ramtusk",ko="대군주 램터스크"},npc={4420}},{id="s5",kind="rare",loot={6679},n="5",name={en="Razorfen Spearhide",ko="가시덩굴일족 가시근위병"},optional=tru